test('ref current is initially null', () => {
  const { result } = renderHook(() => useFocusTrap(true));
  expect(result.current.ref.current).toBeNull();
});

// __hidden__
test('returns stable ref across re-renders', () => {
  const { result, rerender } = renderHook(({ active }) => useFocusTrap(active), {
    initialProps: { active: false }
  });
  const first = result.current.ref;
  rerender({ active: true });
  expect(result.current.ref).toBe(first);
});

solution:
import { useRef, useEffect } from 'react';

const FOCUSABLE_SELECTORS = 'a, button, input, select, textarea, [tabindex]:not([tabindex="-1"])';

export function useFocusTrap(active: boolean) {
  const ref = useRef<HTMLElement>(null);

  useEffect(() => {
    if (!active || !ref.current) return;
    const container = ref.current;

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key !== 'Tab') return;
      const focusable = Array.from(container.querySelectorAll<HTMLElement>(FOCUSABLE_SELECTORS));
      if (focusable.length === 0) { e.preventDefault(); return; }
      const first = focusable[0];
      const last = focusable[focusable.length - 1];
      if (e.shiftKey) {
        if (document.activeElement === first) { e.preventDefault(); last.focus(); }
      } else {
        if (document.activeElement === last) { e.preventDefault(); first.focus(); }
      }
    };

    container.addEventListener('keydown', handleKeyDown);
    return () => container.removeEventListener('keydown', handleKeyDown);
  }, [active]);

  return { ref };
}
